shell_commands:
cat >> src/transport/ws/messageHandler.test.ts <<'EOF'

describe('listing a user conversations over the socket', () => {
  it('answers list_sessions with the summaries of the connection user, dates as ISO strings', async () => {
    const sent: unknown[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw))} as unknown as WebSocket;
    const listFor = jest.fn(async () => [
      {
        sessionId: 's9',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-02T00:00:00.000Z'),
        entryCount: 2,
      },
    ]);
    const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
    const handle = createMessageHandler(orchestrator, {listFor} as unknown as SessionStore);
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    await handle(ws, session, {type: 'list_sessions', limit: 10});

    expect(listFor).toHaveBeenCalledWith('u1', {limit: 10, before: undefined});
    expect(sent).toEqual([
      {
        type: 'session_list',
        sessions: [
          {sessionId: 's9', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-02T00:00:00.000Z', entryCount: 2},
        ],
      },
    ]);
  });
});
EOF
timeout 300 npx jest src/transport/ws/messageHandler.test.ts -t "listing a user conversations" 2>&1 | tail -40
